<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import AdminShell from '@/layouts/AdminShell.vue'
import http, { getErrorMessage } from '@/api/http'
import type { Role } from '../types'
const roles = ref<Role[]>([]); const query = ref(''); const error = ref(''); const success = ref(''); const selected = ref<Role | null>(null); const newName = ref(''); const saving = ref(false); const submitted = ref(false)
const filteredRoles = computed(() => { const value = query.value.trim().toLowerCase(); return roles.value.filter(role => !value || String(role.id_rol).includes(value) || role.name.toLowerCase().includes(value) || role.estatus.nombre_estatus.toLowerCase().includes(value)) })
const validName = () => newName.value.trim().length >= 3 && newName.value.trim().length <= 80
async function load() { try { roles.value = (await http.get<Role[]>('/roles')).data } catch (exception) { error.value = getErrorMessage(exception) } }
function openRename(role: Role) { selected.value = role; newName.value = role.name.replaceAll('_', ' '); submitted.value = false; error.value = ''; success.value = '' }
function closeRename() { selected.value = null; newName.value = ''; submitted.value = false }
async function rename() { submitted.value = true; if (!selected.value || !validName()) return; saving.value = true; error.value = ''; success.value = ''; try { const { data } = await http.patch<Role>(`/roles/${selected.value.id}/name`, { name: newName.value }); success.value = `El rol “${data.name.replaceAll('_', ' ')}” fue actualizado correctamente.`; closeRename(); await load() } catch (exception) { error.value = getErrorMessage(exception) } finally { saving.value = false } }
async function toggleStatus(role: Role) { const activate = role.id_estatus === 2; if (!confirm(`¿${activate ? 'Activar' : 'Suspender'} el rol “${role.name.replaceAll('_', ' ')}”? El registro se conservará.`)) return; saving.value = true; error.value = ''; success.value = ''; try { await http.patch(`/roles/${role.id}/${activate ? 'activate' : 'suspend'}`); success.value = `El rol “${role.name.replaceAll('_', ' ')}” fue ${activate ? 'activado' : 'suspendido'} correctamente.`; await load() } catch (exception) { error.value = getErrorMessage(exception) } finally { saving.value = false } }
onMounted(load)
</script>
<template><AdminShell><section class="page-heading"><div><p class="eyebrow">Administración de roles</p><h1>Administrar roles</h1><p>Actualiza el nombre de un rol o cambia su estado sin eliminar su historial.</p></div></section><p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p><section class="data-card" aria-label="Roles registrados"><div class="data-toolbar"><div><h2>Roles registrados</h2><p>Selecciona un rol para actualizar su nombre, activarlo o suspenderlo.</p></div><label class="search"><span>⌕</span><input v-model="query" placeholder="Buscar por ID, nombre o estatus" /></label></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Nombre del rol</th><th>Estatus</th><th class="align-right">Acciones</th></tr></thead><tbody><tr v-for="role in filteredRoles" :key="role.id"><td class="role-id">{{ role.id_rol }}</td><td><strong>{{ role.name.replaceAll('_', ' ') }}</strong></td><td><span class="status" :class="role.id_estatus === 1 ? 'status-active' : 'status-muted'">{{ role.estatus.nombre_estatus }}</span></td><td class="align-right"><button class="table-action" :disabled="saving" @click="openRename(role)">Actualizar nombre</button><button class="table-action" :class="role.id_estatus === 1 ? 'danger-action' : ''" :disabled="saving" @click="toggleStatus(role)">{{ role.id_estatus === 1 ? 'Suspender' : 'Activar' }}</button></td></tr><tr v-if="!filteredRoles.length"><td colspan="4" class="empty-state">No hay roles que coincidan con la búsqueda.</td></tr></tbody></table></div></section><div v-if="selected" class="modal-backdrop" @click.self="closeRename"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="rename-title"><div class="modal-title"><div><p class="eyebrow">Actualizar nombre</p><h2 id="rename-title">{{ selected.name.replaceAll('_', ' ') }}</h2></div><button class="close-button" aria-label="Cerrar" @click="closeRename">×</button></div><form class="modal-form" @submit.prevent="rename"><label>ID del rol<input :value="selected.id_rol" disabled /></label><label>Nuevo nombre<input v-model="newName" maxlength="80" autofocus /><span v-if="submitted && !validName()">Ingresa un nombre de entre 3 y 80 caracteres.</span></label><p class="field-hint">El ID se conserva. El sistema detecta duplicados aunque cambien mayúsculas o espacios.</p><div class="modal-actions"><button type="button" class="secondary-button" @click="closeRename">Cancelar</button><button class="primary-button" type="submit" :disabled="saving">{{ saving ? 'Actualizando…' : 'Actualizar nombre' }}</button></div></form></section></div></AdminShell></template>
